class Solution { vector<int> parent;int find(int value){return value==parent[value]?value:parent[value]=find(parent[value]);}void unite(int a,int b){parent[find(a)]=find(b);}public: vector<int> findAllPeople(int n,vector<vector<int>>& meetings,int firstPerson){sort(meetings.begin(),meetings.end(),[](auto& a,auto& b){return a[2]<b[2];});parent.resize(n);iota(parent.begin(),parent.end(),0);unite(0,firstPerson);for(int index=0;index<(int)meetings.size();){int end=index,time=meetings[index][2];set<int> participants;while(end<(int)meetings.size()&&meetings[end][2]==time){unite(meetings[end][0],meetings[end][1]);participants.insert(meetings[end][0]);participants.insert(meetings[end][1]);++end;}int root=find(0);for(int person:participants)if(find(person)!=root)parent[person]=person;index=end;}vector<int> answer;for(int person=0;person<n;++person)if(find(person)==find(0))answer.push_back(person);return answer;} };
